// photos.json is generated by `npm run photos` (see scripts/optimize-photos.mjs).
import meta from './photos.json';
import { placeholderImage } from './utils.js';

const base = import.meta.env.BASE_URL;

export const photos = meta.map((m, i) => {
  const label = `Photo ${m.file}`;
  return {
    number: i + 1,
    width: m.w,
    height: m.h,
    full: m.placeholder ? placeholderImage(label, m.w, m.h) : `${base}photos/${m.file}.webp`,
    small: m.placeholder ? placeholderImage(label, m.w, m.h) : `${base}photos/${m.file}-sm.webp`,
  };
});

/** 1-based lookup; falls back to the first photo. */
export const photo = (n) => photos[n - 1] ?? photos[0];
